\n      \"inject\": [],\n      \"platform\": \"web\",\n      \"immediately\": true\n    }\n  },\n  \"dependencies\": {\n    \"commander\": \"^13.1.0\",\n    \"undici\": \"^7.29.0\"\n  },\n  \"devDependencies\": {\n    \"@biomejs/biome\": \"2.5.7\",\n    \"@types/node\": \"^22.19.7\",\n    \"@vitest/coverage-v8\": \"3.2.4\",\n    \"typescript\": \"^5.9.3\",\n    \"vite\": \"^6.4.1\",\n    \"vitest\": \"3.2.4\"\n  }\n}\n"
